var GameResultParser = (function (_super) {
        __extends(GameResultParser, _super);
        function GameResultParser() {
            return _super !== null && _super.apply(this, arguments) || this;
        }
        // Just override the populateResults() method of the base class
        // to parse the additional non-standard nodes / attributes 
        GameResultParser.prototype.parse = function (input, object) {
            _super.prototype.parse.call(this, input, object);
            var node = input.getElementsByTagName("GameResult")[0];
            var resultNodes = node.childNodes;
            var baseGameRecoveryInfo = {
                reelStops: [],
                paylineWins: [],
                scatterWinVal: 0
            };
            var freeSpinResult = {
                fsWinnings: 0,
                freeSpinsTotal: 0,
                freeSpinNumber: 0,
                freeSpinsAwarded: 0,
                isMaxWin: false
            };
            for (var nodeIndex = 0; nodeIndex < resultNodes.length; ++nodeIndex) {
                var childNode = resultNodes[nodeIndex];
                if (childNode.nodeName == "BaseGameRecoveryInfo") {
                    // <ReelResults>
                    var grandchildNodes = childNode.childNodes;
                    var paylineWins = [];
                    for (var i = 0; i < grandchildNodes.length; i++) {
                        var greatGrandchildNodes = grandchildNodes[i].childNodes;
                        for (var j = 0; j < greatGrandchildNodes.length; j++) {
                            if (greatGrandchildNodes[j].nodeName === "ReelSpin") {
                                var greatGreatGrandchildNodes = greatGrandchildNodes[j].childNodes;
                                for (var k = 0; k < greatGreatGrandchildNodes.length; k++) {
                                    if (greatGreatGrandchildNodes[k].nodeName === "ReelStops") {
                                        var reelStops = greatGreatGrandchildNodes[k].textContent;
                                        baseGameRecoveryInfo.reelStops = reelStops.split("|").map(Number);
                                    }
                                    if (greatGreatGrandchildNodes[k].nodeName === "ScatterWin") {
                                        baseGameRecoveryInfo.scatterWinVal = parseInt(greatGreatGrandchildNodes[k].attributes.getNamedItem("winVal").value);
                                    }
                                    else if (greatGreatGrandchildNodes[k].nodeName == "PaylineWin") {
                                        var node = greatGreatGrandchildNodes[k];
                                        var paylineIndex = 0;
                                        var paylineWinVal = 0;
                                        var paylineAwardIndex = 0;
                                        var paylineAwardTableIndex = 0;
                                        var paylineReelPositions = [];
                                        if (node.attributes.getNamedItem("index")) {
                                            paylineIndex = parseInt(node.attributes.getNamedItem("index").value);
                                        }
                                        if (node.attributes.getNamedItem("winVal")) {
                                            paylineWinVal = parseInt(node.attributes.getNamedItem("winVal").value);
                                        }
                                        if (node.attributes.getNamedItem("awardIndex")) {
                                            paylineAwardIndex = parseInt(node.attributes.getNamedItem("awardIndex").value);
                                        }
                                        if (node.attributes.getNamedItem("awardTableIndex")) {
                                            paylineAwardTableIndex = parseInt(node.attributes.getNamedItem("awardTableIndex").value);
                                        }
                                        if (node.textContent) {
                                            paylineReelPositions = node.textContent.split("|").map(Number);
                                        }
                                        paylineWins.push(new server.PaylineWinData(paylineIndex, paylineWinVal, paylineAwardIndex, paylineAwardTableIndex, paylineReelPositions));
                                    }
                                }
                            }
                        }
                    }
                    baseGameRecoveryInfo.paylineWins = paylineWins;
                    object.baseGameRecoveryInfo = baseGameRecoveryInfo;
                }
                if (childNode.nodeName === "BGInfo") {
                    object.totalWagerWin = parseInt(childNode.attributes.getNamedItem("totalWagerWin").value);
                    object.bgWinnings = parseInt(childNode.attributes.getNamedItem("bgWinnings").value);
                    object.isMaxWin = (childNode.attributes.getNamedItem("isMaxWin").value === "1") ? true : false;
                }
                if (childNode.nodeName === "FSInfo") {
                    freeSpinResult.fsWinnings = parseInt(childNode.attributes.getNamedItem("fsWinnings").value);
                    freeSpinResult.freeSpinsTotal = parseInt(childNode.attributes.getNamedItem("freeSpinsTotal").value);
                    freeSpinResult.freeSpinNumber = parseInt(childNode.attributes.getNamedItem("freeSpinNumber").value);
                    freeSpinResult.freeSpinsAwarded = parseInt(childNode.attributes.getNamedItem("freeSpinsAwarded").value);
                    freeSpinResult.isMaxWin = (childNode.attributes.getNamedItem("isMaxWin").value === "1") ? true : false;
                    object.freeSpinResult = freeSpinResult;
                }
            }
        };
        return GameResultParser;
    }(server.GLSGameResultParser));
    game.GameResultParser = GameResultParser;

